    "presrc.faq1.q": "My child doesn't know what to study, what should I do?",
    "presrc.faq1.a": "First step: encourage them to take the Career DNA test on the platform. It reveals their personality type and suitable paths. Then review the results together, without pressure to decide.",
    "presrc.faq2.q": "How can I make sure a university fits our budget?",
    "presrc.faq2.a": "Use the 'study cost calculator' on Masarak. It gives a full estimate: annual fees, books, transport, housing (if out of town). Also check scholarships matching your child's grades.",
    "presrc.faq3.q": "My child wants to study abroad, what do I need to know?",
    "presrc.faq3.a": "Studying abroad costs 3-10 times more than local universities. Make sure the major isn't available at the same quality at home. Consider the international scholarships Masarak offers.",
    "presrc.faq4.q": "How can I track my child's progress on the platform?",
    "presrc.faq4.a": "After linking your account to theirs, you'll see a dashboard of all their progress: Career DNA tests, saved universities, followed scholarships, CV, etc.",
