    "iprep.q.behavioral.1.q": "Tell me about a time you faced a difficult challenge and how you overcame it.",
    "iprep.q.behavioral.1.tip": "Use the STAR technique: Situation, Task, Action, Result.",
    "iprep.q.behavioral.2.q": "How do you deal with a difficult coworker?",
    "iprep.q.behavioral.2.tip": "Focus on the solution, not complaints. Show maturity.",
    "iprep.q.behavioral.3.q": "Tell me about a team project where you led a team.",
    "iprep.q.behavioral.3.tip": "State your role precisely and highlight tangible results.",
    "iprep.q.behavioral.4.q": "How do you manage your time across many tasks?",
    "iprep.q.behavioral.4.tip": "Mention tools (Notion, Trello) and techniques (Pomodoro).",
    "iprep.q.behavioral.5.q": "Tell me about a failure you faced and what you learned from it.",
    "iprep.q.behavioral.5.tip": "Pick a real but small failure, and focus on the lesson.",
    "iprep.q.behavioral.6.q": "How do you handle criticism?",
    "iprep.q.behavioral.6.tip": "Show humility and willingness to improve.",
    "iprep.q.technical.1.q": "What technical skill are you strongest in? Tell me about it.",
    "iprep.q.technical.1.tip": "Give a specific example and a practical project.",
    "iprep.q.technical.2.q": "How do you learn a new technology?",
    "iprep.q.technical.2.tip": "Mention resources (Coursera, YouTube, Documentation).",
    "iprep.q.technical.3.q": "What is the hardest technical problem you have solved?",
    "iprep.q.technical.3.tip": "Explain the problem, the approach, and the solution.",
    "iprep.q.technical.4.q": "Tell me about your latest personal or university project.",
    "iprep.q.technical.4.tip": "Focus on the challenges and technologies used.",
    "iprep.q.technical.5.q": "If your code doesn't work, what are your steps?",
    "iprep.q.technical.5.tip": "Debug systematically: read error → check logic → test.",
    "iprep.q.personal.1.q": "Tell me about yourself in 60 seconds.",
    "iprep.q.personal.1.tip": "Background + major + what sets you apart + your goal. Actually stop at 60 seconds.",
    "iprep.q.personal.2.q": "Why do you want to work at this company / study at this university specifically?",
    "iprep.q.personal.2.tip": "Research it beforehand and mention something specific that distinguishes it.",
    "iprep.q.personal.3.q": "Where do you see yourself in 5 years?",
    "iprep.q.personal.3.tip": "Be ambitious but realistic. Tie your ambition to the company/university.",
    "iprep.q.personal.4.q": "What are your weaknesses?",
    "iprep.q.personal.4.tip": "Pick a real weakness and show how you're working on it.",
    "iprep.q.personal.5.q": "Why should we choose you among all the applicants?",
    "iprep.q.personal.5.tip": "Focus on the added value, not just on yourself.",
    "iprep.q.personal.6.q": "What achievement are you proud of?",
    "iprep.q.personal.6.tip": "Pick an achievement that relates to the role you want.",
    "iprep.q.lebanese.1.q": "How do you view Lebanon's economic situation and its impact on your future?",
    "iprep.q.lebanese.1.tip": "Be optimistic but realistic. Show adaptability.",
    "iprep.q.lebanese.2.q": "Are you thinking of emigrating after graduation?",
    "iprep.q.lebanese.2.tip": "A diplomatic answer: open to opportunities but committed to Lebanon.",
    "iprep.q.lebanese.3.q": "Why did you choose to study in Lebanon rather than abroad?",
    "iprep.q.lebanese.3.tip": "Mention the quality of Lebanese education, family roots, and cost.",
    "iprep.q.lebanese.4.q": "How do you cope with electricity/internet issues in Lebanon?",
    "iprep.q.lebanese.4.tip": "Show adaptability: backup plans, UPS, etc.",
