    "intern.tips.title": "Guide to building a professional student CV",
    "intern.tips.subtitle": "Practical tips from recruiters at top companies in Lebanon and the Gulf",
    "intern.tip1.title": "Tailor your CV to each role",
    "intern.tip1.body": "Read the job description carefully and add the required keywords to your CV. Don't use the same CV for every role.",
    "intern.tip2.title": "Numbers and achievements, not duties",
    "intern.tip2.body": "Instead of 'worked in marketing', write 'raised engagement by 35% in 2 months'. Numbers speak.",
    "intern.tip3.title": "LinkedIn + GitHub + Portfolio",
    "intern.tip3.body": "Add clickable links to your CV. The recruiter will click them. Make sure they're up to date and complete.",
    "intern.tip4.title": "Start with a strong verb",
    "intern.tip4.body": "Start each bullet with a strong past-tense verb: 'developed', 'managed', 'analyzed', 'designed'. Avoid 'responsible for'.",
    "intern.tip5.title": "One page for students",
    "intern.tip5.body": "University student = one page. No need for long personal objectives. The recruiter has 30 seconds.",
